Deque<Integer> data = new ArrayDeque<>();
Deque<Integer> mins = new ArrayDeque<>();

void push(int x) {
    data.push(x);
    if (mins.isEmpty() || x ? mins.peek()) mins.push(x);
}

int pop() {
    int v = data.pop();
    if (v == mins.peek()) mins.pop();
    return v;
}
